Object.entries(creatorStudioTranslations).forEach(([language,entries])=>Object.assign(dict[language],entries));
const reverseEnglish=Object.fromEntries(Object.entries(dict.en).map(([key,value])=>[String(value).trim().toLowerCase(),key]));
const reverseHindi=Object.fromEntries(Object.entries(dict.hi).map(([key,value])=>[String(value).trim().toLowerCase(),key]));
const originalUiText=new WeakMap();
const lastUiTranslation=new WeakMap();
function translateExactText(root){
 const langCode=lang(),map=dict[langCode]||dict.en;
 const scope=root||document;
 const selector="h1,h2,h3,h4,h5,h6,button,label,a,span,th,option,summary";
 const nodes=[];
 if(scope.nodeType===1&&scope.matches?.(selector))nodes.push(scope);
 scope.querySelectorAll?.(selector).forEach(el=>nodes.push(el));
 for(const el of nodes){
  if(el.hasAttribute("data-i18n")||el.closest("[data-user-content],[data-preserve-text],[contenteditable='true'],.caption,.comment,.message,.chat-message,.username,.creator-name,.video-description"))continue;
  if(el.children.length)continue;
  let original=originalUiText.get(el);
  const last=lastUiTranslation.get(el);
  const current=(el.textContent||"").trim();
  if(original===undefined){original=current;originalUiText.set(el,original);}
  else if(current!==last&&current!==original){original=current;originalUiText.set(el,original);}
  const key=reverseEnglish[original.toLowerCase()]||reverseHindi[original.toLowerCase()];
  if(key&&map[key]){if(current!==map[key])el.textContent=map[key];lastUiTranslation.set(el,map[key]);}
  else if(last!==undefined){el.textContent=original;lastUiTranslation.delete(el);}
 }
}
function translateCommonAttributes(root){
 const langCode=lang(),map=dict[langCode]||dict.en;
 root.querySelectorAll?.("[placeholder],[title],[aria-label]").forEach(el=>["placeholder","title","aria-label"].forEach(attr=>{const raw=el.getAttribute(attr);const key=raw&&(reverseEnglish[raw.trim().toLowerCase()]||reverseHindi[raw.trim().toLowerCase()]);if(key&&map[key])el.setAttribute(attr,map[key]);}));
}
function lang(){let p={};try{p=JSON.parse(localStorage.getItem("newstar_preferences")||"{}")}catch(_){}return codes.includes(p.language)?p.language:"hi"}function apply(root=document){const l=lang();document.documentElement.lang=l;document.documentElement.dir=["ar","ur","fa"].includes(l)?"rtl":"ltr";const nodes=[];if(root.nodeType===1&&root.matches?.("[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]"))nodes.push(root);root.querySelectorAll?.("[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]").forEach(n=>nodes.push(n));for(const el of nodes){for(const [a,k] of [["data-i18n","textContent"],["data-i18n-placeholder","placeholder"],["data-i18n-title","title"],["data-i18n-aria-label","aria-label"]]){const key=el.getAttribute(a);const value=key&&dict[l]?.[key];if(value){if(k==="textContent")el.textContent=value;else el.setAttribute(k,value)}}}}window.NewStarTranslations=dict;window.NewStarI18n={apply(root=document){const l=lang();document.documentElement.lang=l;document.documentElement.dir=["ar","ur","fa"].includes(l)?"rtl":"ltr";const scope=root||document;translateExactText(scope);translateCommonAttributes(scope);const nodes=[];if(scope.nodeType===1&&scope.matches?.("[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]"))nodes.push(scope);scope.querySelectorAll?.("[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]").forEach(n=>nodes.push(n));for(const el of nodes){for(const [a,k] of [["data-i18n","textContent"],["data-i18n-placeholder","placeholder"],["data-i18n-title","title"],["data-i18n-aria-label","aria-label"]]){const key=el.getAttribute(a);const value=key&&dict[l]?.[key];if(value){if(k==="textContent")el.textContent=value;else el.setAttribute(k,value)}}}},setLanguage(l){if(!codes.includes(l))return false;if(window.NewStarPreferences?.set)window.NewStarPreferences.set({language:l});else{let p={};try{p=JSON.parse(localStorage.getItem("newstar_preferences")||"{}")}catch(_){}p.language=l;p._updatedAt=new Date().toISOString();localStorage.setItem("newstar_preferences",JSON.stringify(p));window.dispatchEvent(new Event("newstar:preferences-changed"));}window.NewStarI18n.apply();return true},languages:codes.slice()};window.NewStarI18n.apply();new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1)window.NewStarI18n.apply(n);else if(n.nodeType===3&&n.parentElement)translateExactText(n.parentElement)}))).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener("storage",e=>{if(e.key==="newstar_preferences")apply()});
